#!/usr/bin/env node
/**
 * Build assets/data/official.js from data/universities/scorecard.json (spec 004).
 *
 *   node scripts/build-universities.mjs                  write the generated file
 *   node scripts/build-universities.mjs --check          CI: data valid and generated file current
 *   node scripts/build-universities.mjs --summary FILE   also write a Markdown PR summary
 *
 * Deterministic: output depends only on the stored JSON. Zero dependencies; Node 18+.
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import vm from "node:vm";
import { stableStringify, diffRecords, INCOME_BANDS, INCOME_LABELS } from "./lib/scorecard.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const DATA = join(ROOT, "data/universities");
const OUT = join(ROOT, "assets/data/official.js");
const args = process.argv.slice(2);
const CHECK = args.includes("--check");
const SUMMARY = args.includes("--summary") ? args[args.indexOf("--summary") + 1] : null;

const readJson = (f, d) => (existsSync(join(DATA, f)) ? JSON.parse(readFileSync(join(DATA, f), "utf8")) : d);
const sc = readJson("scorecard.json", { source: null, sourceUrl: null, retrieved: null, note: null, schools: {} });
const ids = readJson("scorecard-ids.json", {});
const candidates = readJson("candidates.json", { national: [], states: {} });

/* Our university ids (to catch stale/misspelled keys) */
const ctx = vm.createContext({});
const load = rel => vm.runInContext(readFileSync(join(ROOT, rel), "utf8"), ctx, { filename: rel });
load("assets/data/common/registry.js");
readdirSync(join(ROOT, "assets/data/states")).filter(f => f.endsWith(".js")).sort().forEach(f => load(`assets/data/states/${f}`));
load("assets/data/national.js");
const names = new Map([...Object.values(vm.runInContext("STATES", ctx)).flatMap(s => s.universities), ...vm.runInContext("NATIONAL", ctx).universities].map(u => [u.id, u.name]));

/* ---------- Validate ---------- */
const errors = [];
const isNum = v => v === null || (typeof v === "number" && Number.isFinite(v) && v >= 0);
const isUrl = v => v === null || (typeof v === "string" && /^https:\/\/\S+$/.test(v));
for (const [id, r] of Object.entries(sc.schools || {})) {
  const w = `scorecard.json schools.${id}`;
  if (!names.has(id)) errors.push(`${w}: not a Pathfolio university id`);
  ["tuitionIn", "tuitionOut", "coa", "avgNetPrice", "size", "medianEarnings10yr"].forEach(k => { if (!isNum(r[k] ?? null)) errors.push(`${w}: ${k} must be a non-negative number or null`); });
  ["admissionRate", "gradRate"].forEach(k => { const v = r[k] ?? null; if (!(v === null || (typeof v === "number" && v >= 0 && v <= 1))) errors.push(`${w}: ${k} must be 0–1 or null`); });
  ["url", "priceCalculatorUrl"].forEach(k => { if (!isUrl(r[k] ?? null)) errors.push(`${w}: ${k} must be https or null`); });
  if (r.netPriceByIncome) INCOME_BANDS.forEach(b => { if (!isNum(r.netPriceByIncome[b] ?? null)) errors.push(`${w}: netPriceByIncome.${b} invalid`); });
}
for (const [id, v] of Object.entries(ids)) {
  if (!names.has(id)) errors.push(`scorecard-ids.json ${id}: not a Pathfolio university id`);
  if (!["strong", "weak", "manual", "unresolved"].includes(v.quality)) errors.push(`scorecard-ids.json ${id}: invalid quality "${v.quality}"`);
}
if (errors.length) { console.error("✖ University data problems:\n  " + errors.join("\n  ")); process.exit(1); }

/* ---------- Generate ---------- */
const KEEP = ["unitid", "admissionRate", "size", "tuitionIn", "tuitionOut", "coa", "avgNetPrice", "netPriceByIncome", "gradRate", "medianEarnings10yr", "priceCalculatorUrl", "ownership"];
const official = {
  source: sc.source, sourceUrl: sc.sourceUrl, retrieved: sc.retrieved,
  schools: Object.fromEntries(Object.entries(sc.schools || {})
    .filter(([id]) => !["unresolved"].includes(ids[id]?.quality))
    .map(([id, r]) => [id, { ...Object.fromEntries(KEEP.map(k => [k, r[k] ?? null])), match: ids[id]?.quality || "unknown" }]))
};
const out = `/* AUTO-GENERATED by scripts/build-universities.mjs from data/universities/scorecard.json. Do not edit by hand.
   Official figures from the College Scorecard (U.S. Department of Education). Refreshed monthly by
   .github/workflows/refresh-universities.yml (human-reviewed PR). Spec: specs/004-university-data-pipeline/ */
const OFFICIAL = ${stableStringify(official, 1)};
`;

/* ---------- Summary for the PR ---------- */
if (SUMMARY) {
  const prevText = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  const m = prevText.match(/const OFFICIAL = (\{[\s\S]*\});/);
  let prev = { schools: {} }; try { if (m) prev = JSON.parse(m[1]); } catch { /* first run */ }
  const money = v => (v == null ? "—" : "$" + Math.round(v).toLocaleString("en-US"));
  const pct = v => (v == null ? "—" : Math.round(v * 1000) / 10 + "%");
  const fmt = (k, v) => (["admissionRate", "gradRate"].includes(k) ? pct(v) : money(v));
  const changes = Object.keys(official.schools).sort().map(id => ({ id, d: diffRecords(prev.schools?.[id], official.schools[id]) })).filter(x => x.d.length);
  const weak = Object.entries(ids).filter(([, v]) => v.quality === "weak");
  const unresolved = Object.entries(ids).filter(([, v]) => v.quality === "unresolved");
  const notFetched = [...names.keys()].filter(id => !official.schools[id] && ids[id]?.quality !== "unresolved");
  const candTable = rows => rows.length
    ? "| University | City | Admission rate | Undergrads | Out-of-state tuition |\n|---|---|---|---|---|\n" +
      rows.map(c => `| ${c.url ? `[${c.name}](${/^https?:/i.test(c.url) ? c.url : "https://" + c.url})` : c.name} | ${c.city || ""}, ${c.state || ""} | ${pct(c.admissionRate)} | ${c.size?.toLocaleString("en-US") ?? "—"} | ${money(c.tuitionOut)} |`).join("\n")
    : "_None_";
  const md = [
    `## 🎓 University data refresh: College Scorecard, retrieved ${sc.retrieved || "—"}`,
    `**${Object.keys(official.schools).length} of ${names.size}** listed universities have official figures · **${changes.length}** changed · **${weak.length}** weak matches · **${unresolved.length}** unresolved`,
    sc.note ? `\n> ⚠️ ${sc.note}` : "",
    weak.length ? "\n### 🔎 Please confirm these matches\nIf a match is wrong, set `\"quality\": \"manual\"` with the correct `unitid` in `data/universities/scorecard-ids.json`.\n\n| Pathfolio | Matched to | Score |\n|---|---|---|\n" + weak.map(([id, v]) => `| ${v.ours} (\`${id}\`) | ${v.name} (UNITID ${v.unitid}) | ${v.score} |`).join("\n") : "",
    unresolved.length ? "\n### ❓ Unresolved (add a manual `unitid`)\n" + unresolved.map(([id, v]) => `- ${v.ours} (\`${id}\`): ${v.reason || "no match"}`).join("\n") : "",
    notFetched.length ? "\n### ⏳ Not fetched this run\n" + notFetched.map(id => `- \`${id}\``).join("\n") : "",
    changes.length ? "\n### ✏️ Changed figures\n<details><summary>" + changes.length + " universities</summary>\n\n" + changes.map(c => `- **${names.get(c.id)}**: ` + c.d.map(x => `${x.field} ${fmt(x.field, x.from)} → **${fmt(x.field, x.to)}**`).join("; ")).join("\n") + "\n</details>" : "",
    "\n### 🌟 Discovery: notable universities not yet in Pathfolio (suggestions only)",
    "**Highly selective, national**\n\n" + candTable(candidates.national || []),
    ...Object.entries(candidates.states || {}).map(([s, rows]) => `\n**Large four-year universities in ${s}**\n\n` + candTable(rows)),
    candidates.error ? `\n> Discovery error: ${candidates.error}` : "",
    "\n### Reviewer checklist\n- [ ] Spot-check 3 changed schools on [College Scorecard](https://collegescorecard.ed.gov/)\n- [ ] Confirm or fix weak matches\n- [ ] Open an issue for any suggested university worth adding (curated text is written by people)"
  ].filter(Boolean).join("\n");
  writeFileSync(SUMMARY, md + "\n");
}

if (CHECK) {
  const current = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (current !== out) { console.error("✖ assets/data/official.js is out of date. Run: node scripts/build-universities.mjs"); process.exit(1); }
  console.log(`✓ University data valid and up to date (${Object.keys(official.schools).length} with official figures)`);
} else {
  writeFileSync(OUT, out);
  console.log(`✓ Wrote assets/data/official.js (${Object.keys(official.schools).length} universities)`);
}
export { INCOME_LABELS };
